<html lang="en">
<head>
<meta charset="utf-8">
<title>The State of Global Education - Infographic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2384px;
    height: 3370px;
    background: #1a1d2e;
    font-family: 'Inter', sans-serif;
    color: #e8e6e1;
    overflow: hidden;
  }

  .poster {
    width: 100%;
    height: 100%;
    padding: 80px 90px;
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  /* === HEADER === */
  .header {
    text-align: center;
    padding-bottom: 50px;
    border-bottom: 3px solid rgba(255,255,255,0.08);
    margin-bottom: 50px;
  }
  .header h1 {
    font-size: 82px;
    font-weight: 900;
    letter-spacing: -2px;
    line-height: 1.1;
    color: #ffffff;
    margin-bottom: 18px;
  }
  .header h1 span.accent { color: #f59e42; }
  .header .subtitle {
    font-size: 30px;
    font-weight: 400;
    color: #9ca3af;
    max-width: 1600px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* === PROGRESS SECTION === */
  .progress-section {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 80px;
    padding: 50px 40px;
    background: linear-gradient(135deg, rgba(59,130,246,0.08), rgba(245,158,66,0.08));
    border-radius: 24px;
    margin-bottom: 50px;
  }
  .progress-block {
    text-align: center;
  }
  .progress-block .year {
    font-size: 28px;
    font-weight: 600;
    color: #9ca3af;
    margin-bottom: 8px;
    letter-spacing: 2px;
  }
  .progress-block .big-stat {
    font-size: 110px;
    font-weight: 900;
    line-height: 1;
  }
  .progress-block .big-stat.old { color: #6b7280; }
  .progress-block .big-stat.new { color: #f59e42; }
  .progress-block .stat-label {
    font-size: 24px;
    color: #9ca3af;
    margin-top: 8px;
  }
  .progress-arrow {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
  }
  .progress-arrow .arrow-line {
    width: 180px;
    height: 4px;
    background: linear-gradient(90deg, #6b7280, #f59e42);
    border-radius: 2px;
    position: relative;
  }
  .progress-arrow .arrow-line::after {
    content: '';
    position: absolute;
    right: -12px;
    top: -8px;
    border: 10px solid transparent;
    border-left-color: #f59e42;
  }
  .progress-arrow .arrow-text {
    font-size: 20px;
    color: #d1d5db;
    font-weight: 600;
  }

  /* Icon array for progress */
  .icon-array {
    display: grid;
    grid-template-columns: repeat(10, 1fr);
    gap: 6px;
    width: 260px;
  }
  .icon-array .person {
    width: 20px;
    height: 20px;
    border-radius: 50%;
  }
  .icon-array .person.active { background: #f59e42; }
  .icon-array .person.inactive { background: rgba(255,255,255,0.12); }

  /* === HERO STAT (244M) === */
  .hero-stat {
    text-align: center;
    padding: 65px 40px;
    background: linear-gradient(180deg, rgba(239,68,68,0.12) 0%, rgba(239,68,68,0.04) 100%);
    border: 2px solid rgba(239,68,68,0.25);
    border-radius: 28px;
    margin-bottom: 50px;
    position: relative;
    overflow: hidden;
  }
  .hero-stat::before {
    content: '';
    position: absolute;
    top: -80px;
    right: -80px;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(239,68,68,0.1) 0%, transparent 70%);
  }
  .hero-stat .hero-number {
    font-size: 180px;
    font-weight: 900;
    color: #ef4444;
    line-height: 1;
    letter-spacing: -6px;
    text-shadow: 0 0 80px rgba(239,68,68,0.3);
  }
  .hero-stat .hero-unit {
    font-size: 72px;
    font-weight: 900;
    color: #ef4444;
    opacity: 0.85;
  }
  .hero-stat .hero-label {
    font-size: 38px;
    font-weight: 700;
    color: #fca5a5;
    margin-top: 10px;
    letter-spacing: 1px;
  }
  .hero-stat .hero-sub {
    font-size: 22px;
    color: #9ca3af;
    margin-top: 14px;
    line-height: 1.5;
  }
  .hero-stat .hero-breakdown {
    display: flex;
    justify-content: center;
    gap: 80px;
    margin-top: 30px;
  }
  .hero-stat .breakdown-item {
    text-align: center;
  }
  .hero-stat .breakdown-item .bd-num {
    font-size: 52px;
    font-weight: 900;
    color: #f87171;
  }
  .hero-stat .breakdown-item .bd-label {
    font-size: 18px;
    color: #d1d5db;
    margin-top: 4px;
  }

  /* === MIDDLE ROW: Learning Crisis + Quality Divide === */
  .middle-row {
    display: flex;
    gap: 50px;
    margin-bottom: 50px;
    flex: 1;
  }

  .panel {
    flex: 1;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 24px;
    padding: 50px;
    display: flex;
    flex-direction: column;
  }
  .panel-title {
    font-size: 32px;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 8px;
  }
  .panel-subtitle {
    font-size: 18px;
    color: #9ca3af;
    margin-bottom: 35px;
    line-height: 1.5;
  }

  /* Learning Crisis Panel */
  .crisis-visual {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 30px;
  }
  .crisis-bar-container {
    width: 100%;
    position: relative;
  }
  .crisis-bar-bg {
    width: 100%;
    height: 70px;
    background: rgba(255,255,255,0.06);
    border-radius: 12px;
    overflow: hidden;
    position: relative;
  }
  .crisis-bar-fill {
    width: 20%;
    height: 100%;
    background: linear-gradient(90deg, #f59e42, #ef4444);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .crisis-bar-fill span {
    font-size: 28px;
    font-weight: 900;
    color: #fff;
  }
  .crisis-bar-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 10px;
  }
  .crisis-bar-labels span {
    font-size: 16px;
    color: #9ca3af;
  }
  .crisis-caption {
    font-size: 22px;
    color: #fbbf24;
    font-weight: 600;
    text-align: center;
    line-height: 1.5;
  }
  .crisis-note {
    font-size: 17px;
    color: #6b7280;
    text-align: center;
    font-style: italic;
  }

  /* Quality Divide Panel */
  .quality-compare {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 40px;
  }
  .quality-row {
    display: flex;
    align-items: center;
    gap: 25px;
  }
  .quality-label {
    width: 220px;
    text-align: right;
    font-size: 18px;
    color: #d1d5db;
    font-weight: 600;
    flex-shrink: 0;
  }
  .quality-bar-wrap {
    flex: 1;
    height: 60px;
    background: rgba(255,255,255,0.05);
    border-radius: 10px;
    overflow: hidden;
    position: relative;
  }
  .quality-bar {
    height: 100%;
    border-radius: 10px;
    display: flex;
    align-items: center;
    padding-left: 20px;
    transition: width 0.5s;
  }
  .quality-bar.poor {
    width: 25%;
    background: linear-gradient(90deg, #ef4444, #dc2626);
  }
  .quality-bar.mid {
    width: 58%;
    background: linear-gradient(90deg, #f59e42, #d97706);
  }
  .quality-bar.rich {
    width: 90%;
    background: linear-gradient(90deg, #22c55e, #16a34a);
  }
  .quality-bar .qb-num {
    font-size: 26px;
    font-weight: 900;
    color: #fff;
  }
  .quality-bar .qb-unit {
    font-size: 16px;
    color: rgba(255,255,255,0.8);
    margin-left: 6px;
  }

  /* === GENDER GAP === */
  .gender-section {
    display: flex;
    align-items: center;
    gap: 50px;
    padding: 40px 50px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 24px;
    margin-bottom: 50px;
  }
  .gender-title-block {
    flex-shrink: 0;
  }
  .gender-title-block .panel-title {
    margin-bottom: 6px;
  }
  .gender-items {
    display: flex;
    gap: 40px;
    flex: 1;
  }
  .gender-item {
    flex: 1;
    text-align: center;
    padding: 20px;
    background: rgba(255,255,255,0.03);
    border-radius: 16px;
  }
  .gender-item .gi-level {
    font-size: 20px;
    font-weight: 700;
    color: #c4b5fd;
    margin-bottom: 8px;
  }
  .gender-item .gi-status {
    font-size: 17px;
    color: #d1d5db;
    line-height: 1.4;
  }
  .gender-item .gi-icon {
    font-size: 36px;
    margin-bottom: 8px;
  }

  /* === FOOTER === */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 30px;
    border-top: 2px solid rgba(255,255,255,0.06);
  }
  .footer .takeaway {
    font-size: 22px;
    color: #9ca3af;
    max-width: 1400px;
    line-height: 1.6;
    font-style: italic;
  }
  .footer .source {
    font-size: 16px;
    color: #6b7280;
    text-align: right;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <h1>The State of Global <span class="accent">Education</span></h1>
    <div class="subtitle">Progress, Gaps, and Inequality — A data-driven look at how far the world has come in expanding education access, and the critical gaps that remain.</div>
  </div>

  <!-- PROGRESS SECTION -->
  <div class="progress-section">
    <div class="progress-block">
      <div class="year">1800</div>
      <div class="big-stat old">&lt; 1 in 5</div>
      <div class="stat-label">adults had any formal education</div>
      <div style="margin-top:20px; display:flex; justify-content:center;">
        <div class="icon-array" id="array-old"></div>
      </div>
    </div>
    <div class="progress-arrow">
      <div class="arrow-text">200 YEARS OF PROGRESS</div>
      <div class="arrow-line"></div>
    </div>
    <div class="progress-block">
      <div class="year">TODAY</div>
      <div class="big-stat new">&gt; 4 in 5</div>
      <div class="stat-label">adults have received formal education</div>
      <div style="margin-top:20px; display:flex; justify-content:center;">
        <div class="icon-array" id="array-new"></div>
      </div>
    </div>
  </div>

  <!-- HERO: 244 MILLION -->
  <div class="hero-stat">
    <div class="hero-number">244<span class="hero-unit"> million</span></div>
    <div class="hero-label">CHILDREN STILL OUT OF SCHOOL</div>
    <div class="hero-sub">Despite enormous progress, approximately 244 million children of official school age were not enrolled in primary or secondary education in 2023.</div>
    <div class="hero-breakdown">
      <div class="breakdown-item">
        <div class="bd-num">~60M</div>
        <div class="bd-label">Primary-age children</div>
      </div>
      <div class="breakdown-item">
        <div class="bd-num">~184M</div>
        <div class="bd-label">Secondary-age adolescents</div>
      </div>
    </div>
  </div>

  <!-- MIDDLE ROW -->
  <div class="middle-row">
    <!-- Learning Crisis -->
    <div class="panel">
      <div class="panel-title">The Learning Crisis</div>
      <div class="panel-subtitle">Being in school ≠ learning. Enrollment numbers mask a deeper problem.</div>
      <div class="crisis-visual">
        <div class="crisis-bar-container">
          <div class="crisis-bar-bg">
            <div class="crisis-bar-fill"><span>&lt; 20%</span></div>
          </div>
          <div class="crisis-bar-labels">
            <span>Children achieving minimum reading proficiency</span>
            <span>in low-income countries, end of primary school</span>
          </div>
        </div>
        <div class="crisis-caption">Fewer than 1 in 5 children<br>can read at a basic level</div>
        <div class="crisis-note">"Cannot identify key ideas in a text or connect them to their own experiences"</div>
      </div>
    </div>

    <!-- Quality Divide -->
    <div class="panel">
      <div class="panel-title">A World Divided</div>
      <div class="panel-subtitle">Learning-adjusted years of schooling reveal vast inequality between nations.</div>
      <div class="quality-compare">
        <div class="quality-row">
          <div class="quality-label">Poorest countries<br><span style="font-size:14px;color:#9ca3af;font-weight:400">(parts of Sub-Saharan Africa)</span></div>
          <div class="quality-bar-wrap">
            <div class="quality-bar poor">
              <span class="qb-num">&lt; 3</span><span class="qb-unit">years</span>
            </div>
          </div>
        </div>
        <div class="quality-row">
          <div class="quality-label">South Asia &<br>Sub-Saharan Africa avg.</div>
          <div class="quality-bar-wrap">
            <div class="quality-bar mid">
              <span class="qb-num">&lt; 7</span><span class="qb-unit">years</span>
            </div>
          </div>
        </div>
        <div class="quality-row">
          <div class="quality-label">High-income countries</div>
          <div class="quality-bar-wrap">
            <div class="quality-bar rich">
              <span class="qb-num">10+</span><span class="qb-unit">years</span>
            </div>
          </div>
        </div>
        <div style="text-align:center; margin-top:15px;">
          <span style="font-size:20px; color:#fbbf24; font-weight:600;">Children in the poorest nations receive less than ⅓ of the quality schooling available in wealthy countries.</span>
        </div>
      </div>
    </div>
  </div>

  <!-- GENDER GAP -->
  <div class="gender-section">
    <div class="gender-title-block">
      <div class="panel-title">Closing the Gender Gap</div>
      <div class="panel-subtitle" style="margin-bottom:0">Global enrollment gaps have<br>largely closed — with exceptions.</div>
    </div>
    <div class="gender-items">
      <div class="gender-item">
        <div class="gi-icon">🎒</div>
        <div class="gi-level">Primary</div>
        <div class="gi-status">Nearly closed globally</div>
      </div>
      <div class="gender-item">
        <div class="gi-icon">📚</div>
        <div class="gi-level">Secondary</div>
        <div class="gi-status">Nearly closed globally</div>
      </div>
      <div class="gender-item">
        <div class="gi-icon">🎓</div>
        <div class="gi-level">Tertiary</div>
        <div class="gi-status">Women now exceed men in enrollment</div>
      </div>
      <div class="gender-item" style="background:rgba(239,68,68,0.08); border:1px solid rgba(239,68,68,0.15);">
        <div class="gi-icon">⚠️</div>
        <div class="gi-level" style="color:#fca5a5;">Exceptions</div>
        <div class="gi-status">Countries like Afghanistan: girls far less likely to attend at any level</div>
      </div>
    </div>
  </div>

  <!-- FOOTER -->
  <div class="footer">
    <div class="takeaway">"The world has achieved remarkable progress — but the job is far from done. Hundreds of millions of children are either out of school or learning very little while in it."</div>
    <div class="source">Data: UNESCO, World Bank (2020–2023)<br>Our World in Data</div>
  </div>

</div>

<script>
  // Generate icon arrays
  function fillArray(id, activeCount) {
    const el = document.getElementById(id);
    for (let i = 0; i < 20; i++) {
      const dot = document.createElement('div');
      dot.className = 'person ' + (i < activeCount ? 'active' : 'inactive');
      el.appendChild(dot);
    }
  }
  fillArray('array-old', 4);   // ~1 in 5 = 4 of 20
  fillArray('array-new', 16);  // ~4 in 5 = 16 of 20
</script>
</body>
</html>
